/**
 * emit to subscription queries of type FindClinicalOrder,
 * but only if the id matches
 *
 * @param		entity	ClinicalOrder
 */
	protected void emitFindClinicalOrder( ClinicalOrder entity ) {
		LOGGER.info("handling emitFindClinicalOrder" );
		
	    queryUpdateEmitter.emit(FindClinicalOrderQuery.class,
	                            query -> query.getFilter().getClinicalOrderId().equals(entity.getClinicalOrderId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllClinicalOrder
	 * 
	 * @param		entity	ClinicalOrder
	 */
	protected void emitFindAllClinicalOrder( ClinicalOrder entity ) {
		LOGGER.info("handling emitFindAllClinicalOrder" );
		
	    queryUpdateEmitter.emit(FindAllClinicalOrderQuery.class,
	                            query -> true,
	                            entity);
	}

